    poet: `கனிமேதவியார்`,
    poetEnglish: `Kaṉimēytaviyar`,
    speaker: `தலைவன்`,
    speakerEnglish: `The hero, to his friend`,
    turai: `தலைவன் மலை அழகை வர்ணித்தது`,
    turaiEnglish: `The hero praises the mountain landscape`,
