    altTranslation: `Marutam bloomed; the sandy bank was full. The brooding hearts merged into one. He reformed and came back reformed. She who had suffered forgot her suffering.`,
    note: `Poem 85 of the Marutam section (63–93). Landscape elements — கரும்பு (sugarcane) and வண்டு (bee) — frame the friend describes the reconciliation. One of 31 poems in this tiṇai that Kaṉimēytaviyar weaves into the garland of 154 landscape stanzas.`
