    tamilUrai: `இப்பாடலில் பாலை திணையின் தலைவி மலர்கள் பார்த்து வருந்தியது என்ற நிலை காட்டப்படுகிறது. இலவம் (silk cotton) மற்றும் ஓந்தி (monitor lizard) போன்ற இயற்கை அம்சங்கள் காதலை வெளிப்படுத்துகின்றன.`,
    altTranslation: `Even in the wasteland flowers bloom; like vēy they do their work without pause. Like roots that only do their work they stand — I wait until the season comes.`,
