    tamilUrai: `இப்பாடலில் பாலை திணையின் தலைவன் இறுதி கட்டத்தில் நினைத்தது என்ற நிலை காட்டப்படுகிறது. வேம்பு (neem) மற்றும் பாம்பு (serpent) போன்ற இயற்கை அம்சங்கள் காதலை வெளிப்படுத்துகின்றன.`,
    altTranslation: `Though the burning sun gives trouble, I walk. My seared heart longs for wide shade. When I cross the dark road I will find it — without wandering, I will return.`,
